WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 1 HOUR THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, pressure, status_bits, firmware, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, DATE_TRUNC('DAY', reading_ts) AS activity_day, MAX(reading_ts) AS last_reading_ts, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS pressure_per_dv_01, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, BIT_AND(status_bits) AS status_bits_bit_and, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, MAX(burst_id) FILTER (WHERE device_code = 'DV-03') AS dv_03_max_burst_id FROM sessions_device_readings GROUP BY DATE_TRUNC('HOUR', reading_ts), DATE_TRUNC('DAY', reading_ts) ORDER BY dv_02_rows;
